import { useEffect, useState } from 'react'
import { Navigate, Route, Routes, useNavigate } from 'react-router-dom'
import { MapPin, WashingMachine } from 'lucide-react'
import { apiGet, apiRequest, currentSession, signInWithApi, signOut } from '@laundry-desk/shared-ui'

function CustomerLogin(){const navigate=useNavigate(),[email,setEmail]=useState('pelanggan@laundrydesk.test'),[password,setPassword]=useState('Laundry123!'),[error,setError]=useState(''),[loading,setLoading]=useState(false);async function login(){setLoading(true);setError('');try{const user=await signInWithApi(email,password,'customer-web');if(user.role!=='customer')throw new Error('Gunakan akun pelanggan untuk web ini.');navigate('/pelanggan')}catch(reason){setError(reason instanceof Error?reason.message:'Login gagal.')}finally{setLoading(false)}}return <main className="shell"><section className="card"><div className="mark"><WashingMachine/></div><p className="eyebrow">LAUNDRY DESK</p><h1>Cuci jadi lebih dekat.</h1><p>Temukan outlet sekitar, pilih layanan, lalu pantau pesananmu.</p><label>Email<input value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Kata sandi<input type="password" value={password} onChange={e=>setPassword(e.target.value)}/></label>{error&&<small>{error}</small>}<button onClick={login} disabled={loading}>{loading?'Memeriksa akun...':'Masuk'}</button><small>Gunakan akun pelanggan demo dari Laravel.</small></section></main>}
type Store={id:number;name:string;address:string;phone:string};type Service={id:number;name:string;description:string;price:string;unit:string};function CustomerHomeLive(){const user=currentSession(),navigate=useNavigate();const[stores,setStores]=useState<Store[]>([]),[services,setServices]=useState<Service[]>([]),[storeId,setStoreId]=useState<number|undefined>(),[serviceId,setServiceId]=useState<number|undefined>(),[quantity,setQuantity]=useState(1),[notice,setNotice]=useState(''),[saving,setSaving]=useState(false);useEffect(()=>{apiGet<{data:Store[]}>('/stores').then(result=>setStores(result.data)).catch(()=>setNotice('Daftar outlet belum dapat dimuat.'))},[]);if(!user||user.role!=='customer')return <Navigate to="/masuk" replace/>;async function chooseStore(id:number){setStoreId(id);setServiceId(undefined);setNotice('');try{const result=await apiGet<Service[]>(`/services?store_id=${id}`);setServices(result);setServiceId(result[0]?.id)}catch{setNotice('Layanan outlet belum dapat dimuat.')}}const service=services.find(item=>item.id===serviceId);async function createOrder(){if(!storeId||!serviceId)return;setSaving(true);setNotice('');try{await apiRequest('/orders','POST',{store_id:storeId,payment_method:'transfer',items:[{service_id:serviceId,quantity}]});setNotice('Pesanan berhasil dibuat. Status awalnya: baru.');}catch(reason){setNotice(reason instanceof Error?reason.message:'Pesanan belum dapat dibuat.')}finally{setSaving(false)}}return <main className="customer"><header><div className="logo"><WashingMachine size={22}/> Laundry Desk</div><button className="link" onClick={()=>{signOut();navigate('/masuk')}}>Keluar</button></header><section className="hero"><p className="eyebrow">HALO, {user.name.toUpperCase()}</p><h1>Pilih outlet dan layanan</h1><p>Outlet ditampilkan dari data toko aktif. Untuk fitur peta penuh, gunakan koordinat toko yang sudah tersedia di backend.</p><article><MapPin color="#397fa6"/><div><b>Outlet tersedia</b><span>Pilih outlet yang paling nyaman untukmu.</span></div></article><div className="map-placeholder">{stores.map(store=><button className="link" key={store.id} onClick={()=>chooseStore(store.id)}><b>{storeId===store.id?'✓ ':''}{store.name}</b><br/>{store.address}</button>)}</div>{storeId&&<><label>Layanan<select value={serviceId??''} onChange={event=>setServiceId(Number(event.target.value))}>{services.map(item=><option value={item.id} key={item.id}>{item.name} - Rp {Number(item.price).toLocaleString('id-ID')}/{item.unit}</option>)}</select></label><label>Jumlah / berat<input min="1" type="number" value={quantity} onChange={event=>setQuantity(Number(event.target.value))}/></label>{service&&<p>Total perkiraan: <b>Rp {(Number(service.price)*quantity).toLocaleString('id-ID')}</b></p>}<button disabled={saving||!serviceId} onClick={createOrder}>{saving?'Membuat pesanan...':'Buat pesanan'}</button></>}{notice&&<small>{notice}</small>}</section></main>}
export function App(){return <Routes><Route path="/masuk" element={<CustomerLogin/>}/><Route path="/pelanggan" element={<CustomerHomeLive/>}/><Route path="*" element={<Navigate to={currentSession()?.role==='customer'?'/pelanggan':'/masuk'} replace/>}/></Routes>}
